from airflow.decorators import dag, task
from datetime import datetime

@dag(schedule="@daily", start_date=datetime(2026, 1, 1), catchup=False)
def daily_report_dag():

    @task
    def extract():
        return {"rows": 42}

    @task
    def load(data: dict):
        print(f"loading {data['rows']} rows")

    extracted = extract()
    load(extracted)

daily_report_dag()

